<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Infrastructure\Driver;

use Override;
use Civi\Lughauth\Shared\Infrastructure\MicroPlugin;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Infrastructure\Driven\UserAcceptedTermnsOfUseReadRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Infrastructure\Driven\UserAcceptedTermnsOfUseWriteRepositoryAdapter;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\Gateway\UserAcceptedTermnsOfUseReadGateway;
use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\Gateway\UserAcceptedTermnsOfUseWriteGateway;

class UserAcceptedTermnsOfUsePlugin extends MicroPlugin
{
    #[Override]
    public function registerServiceDefinition(array $def): array
    {
        $def[UserAcceptedTermnsOfUseReadGateway::class] = \DI\autowire(UserAcceptedTermnsOfUseReadRepositoryAdapter::class);
        $def[UserAcceptedTermnsOfUseWriteGateway::class] = \DI\autowire(UserAcceptedTermnsOfUseWriteRepositoryAdapter::class);
        return $def;
    }
}
